from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DIST = ROOT / 'dist'
EMAIL = 'designs@chadrosedigital.co.za'
ARROW = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'
CHECK = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'


SILVER_STAR = '<svg class="mobile-star" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 1.5 15 9l7.5 3L15 15l-3 7.5L9 15l-7.5-3L9 9Z" fill="#b8bcc4" stroke="#8b919a" stroke-width=".6" stroke-linejoin="round"/></svg>'

def device_symbol(desktop, mobile=None):
    return f'<span class="device-symbol" aria-hidden="true"><span class="desktop-symbol">{desktop}</span><span class="mobile-symbol">{mobile if mobile is not None else desktop + chr(0xfe0e)}</span></span>'

def button(label, href='contact.html', style='primary', extra=''):
    return f'<a class="button {style}" href="{href}" {extra}>{label}{ARROW}</a>'

def pricing():
    common = ['Professional, mobile-responsive design','Contact or booking button','6 revision rounds per year after final site approval']
    out = '<div class="pricing-grid">'
    for name,price,pages,recommended in [('Landing Page','2,000','Single-page website',False),('Full Website','5,000','Up to 5 pages',True)]:
        out += f'''<article class="price-card {'recommended' if recommended else ''}" data-reveal data-delay="{100 if recommended else 0}"><div class="plan-heading"><h3>{name}</h3><span class="plan-icon" aria-hidden="true">{device_symbol('✦') if recommended else SILVER_STAR}</span></div><p class="plan-description">{'Room to tell your story. Built to grow your business.' if recommended else 'One beautiful page. One clear next step.'}</p><p class="price"><span>R{price}</span><small>per annum</small></p><ul>{''.join(f'<li>{CHECK}<span>{x}</span></li>' for x in [pages]+common)}</ul>{button('Let’s build your website' if recommended else 'Start with a landing page', 'contact.html?package='+('full-website' if recommended else 'landing-page'), 'light' if recommended else 'outline')}<p class="deposit-note">50% upfront · Balance before launch</p></article>'''
    return out+'</div>'

FAQS = [
('How does payment work?','A 50% deposit is required upfront. The remaining 50% is payable before your website launches. The Landing Page package is R2,000 per annum and the Full Website package is R5,000 per annum.'),
('What counts as a revision round?','A revision round is one consolidated set of changes. Both packages include six revision rounds per year after the final site is approved. We’ll agree on the scope of your updates together.'),
('Can people contact or book with me through the site?','Yes. Your contact or booking button can link to WhatsApp, email, or an external booking platform, depending on how you prefer to hear from customers.'),
('Do I need to know anything about websites?','No. Book a call, tell us about your business, and we’ll guide the design and build. You’ll have a chance to review the website before it goes live.'),
('How long will it take?','We’ll agree on a realistic timeline after learning about your business, page requirements, and the content available. Your project starts with a clear scope and next steps.'),
('What if I already have a website?','Send us the link. We can discuss what’s working, what needs to change, and whether a landing page or a full website is the better fit.')]

def faqs(items=FAQS):
    return '<div class="faq-list">'+''.join(f'<details data-reveal><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'

def cta():
    return f'''<section class="cta-section"><div class="container cta-inner" data-reveal><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>Let’s make your business<br><em>look the part.</em></h2></div><div class="cta-action">{button('Book a discovery call','contact.html?package=call','light')}<p>No complicated brief needed.<br>Just a conversation about your business.</p></div></div></section>'''

def intro(kicker,title,description):
    return f'<section class="page-intro container"><span class="eyebrow" data-reveal>{kicker}</span><h1 data-reveal data-delay="70">{title}</h1><p data-reveal data-delay="140">{description}</p></section>'

def home():
    return f'''<section class="hero-surface"><div class="home-hero container"><div class="hero-copy"><span class="eyebrow" data-reveal><i class="status-dot"></i> CHAD ROSE DIGITAL / WEB DESIGN</span><h1 data-reveal data-delay="80">Premium websites.<br><em>Without premium<br class="desktop-br"> prices.</em></h1><p class="hero-description" data-reveal data-delay="150">Give your business the presence it deserves. Beautiful, thoughtfully built websites that make a lasting first impression.</p><div class="hero-actions" data-reveal data-delay="220">{button('Find your website','pricing.html')}{button('How it works','how-it-works.html','text')}</div></div><div class="hero-stage prestige-stage" data-reveal data-delay="180"><div class="stage-orbit" aria-hidden="true"></div><div class="monitor-device" aria-hidden="true"><div class="monitor-frame"><div class="monitor-screen"><div class="prestige-art"><img class="monitor-artwork" src="assets/luxe-cr-digital-gold-monogram.png" width="1672" height="941" alt="" fetchpriority="high"></div></div><div class="monitor-chin"><i></i></div></div><div class="monitor-stand"></div><div class="monitor-foot"></div></div></div></div></section>
    <div class="benefit-strip container"><span>{CHECK} Designed around your business</span><span>{CHECK} Beautiful on mobile</span><span>{CHECK} Clear annual pricing</span><span>{CHECK} Human, personal service</span></div>
    <section class="section container"><div class="section-heading" data-reveal><div><span class="eyebrow">LOOK GOOD. MAKE IT COUNT.</span><h2>A small business.<br><em>A big first impression.</em></h2></div><p>Your website should feel like you’ve already arrived. We bring thoughtful design, clear messaging, and an easy next step together in one polished experience.</p></div><div class="value-grid"><article data-reveal><span class="line-icon">01 /</span><h3>Look the part.</h3><p>A distinctive online presence that helps visitors feel confident about choosing you.</p></article><article data-reveal data-delay="90"><span class="line-icon">02 /</span><h3>Make it effortless.</h3><p>Clear pages, easy navigation, and contact buttons that turn interest into a conversation.</p></article><article data-reveal data-delay="180"><span class="line-icon">03 /</span><h3>Keep it simple.</h3><p>Two annual packages, a straightforward process, and someone to guide you from idea to launch.</p></article></div></section>
    <section class="section dark-pricing"><div class="container"><div class="section-heading" data-reveal><div><span class="eyebrow">A REFRESHINGLY SIMPLE INVESTMENT</span><h2>Good design.<br><em>Great value.</em></h2></div><p>You don’t need a premium budget to have a premium presence. Choose the right fit for your business.</p></div>{pricing()}<div class="section-footer"><span>All prices in South African rand. Annual packages.</span><a class="text-link" href="pricing.html">Compare the details {ARROW}</a></div></div></section>
    <section class="section simple-process"><div class="container process-teaser"><div data-reveal><span class="eyebrow">LESS TO MANAGE. MORE TO LOOK FORWARD TO.</span><h2>You bring the business.<br><em>We’ll take it from there.</em></h2>{button('See how it works','how-it-works.html','outline')}</div><ol class="mini-steps"><li data-reveal><span>01</span><div><h3>Book a call</h3><p>Tell us what you do and what you have in mind.</p></div></li><li data-reveal><span>02</span><div><h3>We design & build</h3><p>Your business takes shape online, with your input along the way.</p></div></li><li data-reveal><span>03</span><div><h3>Review, then launch</h3><p>Approve the details and get ready for your next first impression.</p></div></li></ol></div></section>{cta()}'''

def how():
    steps=[('A conversation, not a complicated brief.','Book a call. Tell us about your business, your customers, and what you want the website to do. We’ll help you choose the right package.','You bring: your ideas and a little time.'),('We turn your business into a direction.','We agree on the pages and content, then shape a visual direction around your business. Once the scope is agreed and the 50% deposit is paid, we get to work.','We handle: structure, visual design, and the build.'),('You get the final say.','Review your website and share your feedback. We refine the details together so it feels right before it goes live.','You see: a website that’s ready for the real world.'),('Ready for your next first impression.','The remaining balance is paid before launch. After final approval, your package includes six revision rounds per year to keep the site feeling current.','Your next step: share your website with confidence.')]
    return intro('HOW IT WORKS','Your business.<br><em>Our next great project.</em>','Simply book a call, tell us about your business, and we’ll take care of the design and build. Clear steps. Personal guidance. No technical expertise required.')+f'''<section class="container journey-section">{''.join(f'<article class="journey-step" data-reveal><span class="journey-number">0{i+1}</span><div><span class="eyebrow">{["LET’S TALK","DESIGN & BUILD","REVIEW & REFINE","LAUNCH & BE SEEN"][i]}</span><h2>{title}</h2><p>{desc}</p><span class="journey-note">{note}</span></div></article>' for i,(title,desc,note) in enumerate(steps))}</section><section class="section container compact-section"><div class="section-heading" data-reveal><div><span class="eyebrow">A LITTLE PREPARATION GOES A LONG WAY</span><h2>Have these handy.<br><em>We’ll guide the rest.</em></h2></div><p>Your business name, a short description of what you do, any existing logo or photos, and the best way for customers to contact you. If you’re unsure what you need, we’ll discuss it on the call.</p></div></section>{cta()}'''

def prices():
    return intro('PRICING','The premium look.<br><em>The pleasant surprise.</em>','Two clear annual packages. Thoughtful design, a personal approach, and a website built around your business.')+f'''<section class="container pricing-page">{pricing()}<div class="payment-banner" data-reveal><div class="payment-symbol" aria-hidden="true">50<span>%</span></div><div><h3>A straightforward start.</h3><p>50% deposit upfront. The balance is payable before launch.<br>Prices are per annum, in South African rand.</p></div></div></section><section class="section container faq-section"><div data-reveal><span class="eyebrow">GOOD QUESTIONS</span><h2>A few things<br><em>worth knowing.</em></h2><p>Still have something on your mind?</p><a class="text-link" href="contact.html">Let’s talk {ARROW}</a></div>{faqs()}</section>{cta()}'''

def contact():
    return f'''<section class="container contact-layout"><div class="contact-copy"><span class="eyebrow" data-reveal>LET’S MAKE SOMETHING GREAT</span><h1 data-reveal data-delay="70">Your next<br>first impression<br><em>starts here.</em></h1><p data-reveal data-delay="140">Tell us a little about your business. We’ll start with a conversation and help you find the right fit.</p><div class="contact-direct" data-reveal><span class="eyebrow">PREFER TO EMAIL DIRECTLY?</span><a href="mailto:{EMAIL}">{EMAIL} {device_symbol("↗")}</a><button class="copy-email" type="button" data-copy-email>Copy email address</button><span id="copy-status" class="form-status" role="status"></span></div><div class="contact-reassurance" data-reveal>{CHECK}<span>No technical brief needed.<br>Just tell us what you have in mind.</span></div></div><div class="enquiry-panel" data-reveal data-delay="150"><div class="form-heading"><span class="eyebrow">LET’S GET TO KNOW YOUR BUSINESS</span><h2>Start a conversation.</h2><p>Request a call or ask about a website.</p></div><form id="enquiry-form"><div class="form-row"><div class="field"><label for="name">Your name <span>*</span></label><input id="name" name="name" autocomplete="name" placeholder="Name and surname" required maxlength="100"></div><div class="field"><label for="email">Email address <span>*</span></label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@business.com" required maxlength="150"></div></div><div class="field"><label for="business">Business name</label><input id="business" name="business" autocomplete="organization" placeholder="What’s your business called?" maxlength="150"></div><div class="field"><label for="package">I’m interested in</label><select id="package" name="package"><option value="full-website">Full Website — R5,000 / year</option><option value="landing-page">Landing Page — R2,000 / year</option><option value="call">A discovery call / help choosing</option></select></div><div class="field"><label for="message">A little about your business <span>*</span></label><textarea id="message" name="message" rows="4" placeholder="What do you do, and what would you like your website to help with? If you’d like a call, include a good time to reach you." required maxlength="2000"></textarea></div><button class="button primary submit-button" type="submit">Prepare my enquiry {ARROW}</button><p class="form-explainer">This opens a prepared email in your email app. Review it and press send when you’re ready.</p><div id="form-result" class="form-result" hidden><p>Your enquiry is ready in your email app. If it didn’t open, copy the message below and email it to <a href="mailto:{EMAIL}">{EMAIL}</a>.</p><button class="copy-email" type="button" id="copy-enquiry">Copy enquiry</button><span id="enquiry-status" role="status"></span></div></form></div></section>'''

NAV=[('Home','index.html'),('How it works','how-it-works.html'),('Pricing','pricing.html'),('Contact','contact.html')]

def render(filename,title,description,content):
    links=''.join(f'<a href="{href}" {"aria-current=\"page\"" if href==filename else ""}>{label}</a>' for label,href in NAV)
    if filename == 'index.html':
        content = content.replace('class="section container"', 'class="section container" id="services"', 1).replace('class="section simple-process"', 'class="section simple-process" id="process"').replace('class="cta-section"', 'class="cta-section" id="contact"')
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b0b0b"><meta name="description" content="{description}"><title>{title} | Chad Rose Digital</title><meta property="og:title" content="{title} | Chad Rose Digital"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><link rel="icon" href="favicon.png" type="image/png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap" rel="stylesheet"><link rel="stylesheet" href="site.css"><link rel="stylesheet" href="prestige.css"><script src="site.js" defer></script><noscript><style>@media(max-width:600px){{.site-header{{height:auto;padding:18px 0}}.nav-shell{{flex-wrap:wrap}}.menu-toggle{{display:none}}.main-nav{{display:flex;position:static;flex-wrap:wrap;gap:14px;padding:0;border:0;box-shadow:none}}.main-nav a{{font-size:12px;padding:8px 0}}}}</style></noscript></head><body id="top"><a class="skip-link" href="#main">Skip to content</a><div class="scroll-progress" aria-hidden="true"></div><header class="site-header"><div class="container nav-shell"><a class="brand" href="index.html" aria-label="Chad Rose Digital home"><img class="brand-logo" src="assets/crd-logo.png" width="318" height="171" alt=""><span class="brand-wordmark">CHAD ROSE<span>DIGITAL</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false"><span></span><span></span></button><nav id="main-nav" class="main-nav" aria-label="Main navigation">{links}</nav>{button('Let’s talk','contact.html','nav-button')}</div></header><main id="main">{content}</main><footer class="site-footer"><div class="container"><div class="footer-top"><a class="brand footer-brand" href="index.html" aria-label="Chad Rose Digital home"><img class="brand-logo" src="assets/crd-logo.png" width="318" height="171" alt=""><span class="brand-wordmark">CHAD ROSE<span>DIGITAL</span></span></a><p>Premium websites.<br>Without premium prices.</p><a class="footer-email" href="mailto:{EMAIL}">{EMAIL} {device_symbol("↗")}</a></div><div class="footer-bottom"><span>{device_symbol("©")} <span id="year">2026</span> Chad Rose Digital</span><nav aria-label="Footer navigation">{links}</nav><a href="#main" class="back-top">Back to top {device_symbol("↑")}</a></div></div></footer></body></html>'''
    (DIST/filename).write_text(html)

if __name__ == '__main__':
    render('index.html','Premium websites. Without premium prices.','Beautiful websites for your business. Landing pages from R2,000 per annum and full websites from R5,000 per annum.',home())
    render('how-it-works.html','How it works','Book a call, tell us about your business, and let Chad Rose Digital take care of the website design and build.',how())
    render('pricing.html','Simple annual website pricing','Landing Page: R2,000 per annum. Full Website: R5,000 per annum. 50% deposit upfront, balance before launch.',prices())
    render('contact.html','Let’s talk about your website','Enquire about a website or request a discovery call with Chad Rose Digital.',contact())
